(2814, 'Free Study 2019-03', 'Description Free Study for March, 2019.', '2019-03-01', '2019-03-31', '2019-04-01', '2019-04-07', 71, 0, 3508, 107, 5.82013, 7.6863, 5.67675, 4.4694),
(2815, 'In the style of Uta Barth', 'Description Find beauty in the periphery of our vision.', '2019-03-04', '2019-03-17', '2019-03-18', '2019-03-24', 53, 0, 2548, 50, 5.67111, 7.0208, 5.6842, 5.0417),
(2816, 'Fish II', 'Description N/A', '2019-03-06', '2019-03-19', '2019-03-20', '2019-03-26', 33, 0, 1772, 50, 5.5553, 6.4717, 5.4953, 4.6226),
(2817, 'Shelf/Shelves', 'Description Take a photo that includes a shelf or a set of shelves and whatever you find, or choose to place, upon them.', '2019-03-08', '2019-03-21', '2019-03-22', '2019-03-28', 30, 0, 1352, 98, 5.80104, 7.0, 5.7778, 4.8182),
(2818, 'Macro Without Bugs or Flowers V', 'Description Take a macro shot (or at least an extreme close-up) of something that is NOT a bug or a flower. For the purpose of this challenge, "bug" refers to any insect, arachnid, worm, larva, etc. that would be classified in the arthropoda phylum.', '2019-03-11', '2019-03-24', '2019-03-25', '2019-03-31', 49, 0, 2262, 58, 5.50707, 7.234, 5.48405, 4.25),
(2819, 'Snapshot III', 'Description Let''s do snapshots like it''s still 1965 and we just dropped a roll of film off to the drugstore to be processed :-)', '2019-03-13', '2019-03-26', '2019-03-27', '2019-04-02', 41, 3, 1846, 105, 5.79361, 6.6, 5.92145, 4.413),
(2820, 'Abandoned Buildings V', 'Description Abandoned buildings often have unique textures, colors, and character. Show us a great photograph of a building that is no longer in use.', '2019-03-15', '2019-03-28', '2019-03-29', '2019-04-04', 37, 0, 1754, 69, 5.54903, 6.2553, 5.45365, 4.6809),
(2821, 'Extended Free Study 2019-03', 'Description Extended Free Study for March, 2019.', '2019-03-15', '2019-04-14', '2019-04-15', '2019-04-21', 46, 0, 1840, 46, 5.82989, 6.9231, 5.878, 4.725),
(2822, 'On the Road II', 'Description Let''s re-explore the 10th-ever DPC Challenge using the original challenge description: "Let your imagination run wild, but just keep it on the road."', '2019-03-18', '2019-03-31', '2019-04-01', '2019-04-07', 36, 0, 2066, 109, 5.6728, 7.0, 5.5263, 4.875),
(2823, 'Archaeology', 'Description According to Wikipedia, Archaeology is the study of human cultures through the recovery, documentation and analysis of material remains and environmental data, including architecture, artifacts, biofacts, human remains, and landscapes.', '2019-03-20', '2019-04-02', '2019-04-03', '2019-04-09', 18, 0, 931, 22, 5.6101, 6.7547, 5.4118, 4.5192),
