(3782, 'Surrealism IV', 'N/A', '2024-05-17', '2024-05-30', '2024-05-31', '2024-06-06', 19, 0, 509, 11, 5.98232, 6.5926, 5.92525, 4.8148),
(3783, 'Photo Diary', 'Take a shot that represents a day in your life.', '2024-05-20', '2024-06-02', '2024-06-03', '2024-06-09', 20, 0, 428, 8, 5.67991, 6.3182, 5.6667, 4.8636),
(3784, 'Postmodernism', 'Many people say we live in a "postmodern age." Communicate what that means in a photo.', '2024-05-22', '2024-06-04', '2024-06-05', '2024-06-11', 17, 1, 437, 13, 5.79176, 6.9615, 5.8875, 4.24),
