(3797, 'Flora V', '"Flora" refers generally to all plant life, not just flowers.', '2024-06-17', '2024-06-30', '2024-07-01', '2024-07-07', 27, 0, 475, 11, 5.76842, 6.5, 5.80555, 4.8824),
(3799, 'Good Morning!', 'This week, shoot anything having to do with morning...', '2024-06-19', '2024-07-02', '2024-07-03', '2024-07-09', 12, 0, 234, 10, 5.89316, 6.8, 5.7368, 5.2632),
(3800, 'Window Sill', 'The window sill can be a landscape, a still life, or a stage. Take a picture of it.', '2024-06-21', '2024-07-04', '2024-07-05', '2024-07-11', 18, 0, 406, 21, 5.8202, 7.1304, 5.8696, 4.5),
